function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,utarg,tstarg,nstarg)
[u] = ver_reg(ws,t_out,te,ks,ns,reg,est);
[uref] = ver_reg(utarg,t_out,tstarg,ks,nstarg,reg,est);
Fout = 0.0   ;
Eenz = 1.937 ;
Csol = 80;   ;
Gsol = 0     ;
k = 0.0257458;
Km = 11.6035;;
Kig = 5.38839;

y(1)=( u(2) + u(1)                          );
y(2)=( (u(2)/y(1))*Gsol                     );
y(3)=( (u(1)/y(1))*Eenz                     );
y(4)=( k*x(3)*x(1)/(Km*(1+ x(2)/Kig) + x(1)));
y(5)=( (u(2)/y(1))*Csol                     );

dx(1)=((y(1)/x(4))*(y(5)-x(1)) - y(4)      )*tal;
dx(2)=((y(1)/x(4))*(y(2)-x(2)) + 1.111*y(4))*tal;
dx(3)=((y(1)/x(4))*(y(3)-x(3))             )*tal;
dx(4)=((y(1)-Fout)                         )*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
